def open_lock(deadends, target):
    dead = set(deadends)
    if "0000" in dead:
        return -1
    seen, queue = {"0000"}, deque([("0000", 0)])
    while queue:
        state, moves = queue.popleft()
        if state == target:
            return moves
        for i in range(4):
            d = int(state[i])
            for nd in ((d + 1) % 10, (d - 1) % 10):
                nxt = state[:i] + str(nd) + state[i + 1:]
                if nxt not in seen and nxt not in dead:
                    seen.add(nxt)
                    queue.append((nxt, moves + 1))
    return -1

def open_lock(deadends, target):
    dead = set(deadends)
    if "0000" in dead or target in dead:
        return -1
    if target == "0000":
        return 0
    front, back, seen = {"0000"}, {target}, {"0000", target}
    moves = 0
    while front and back:
        if len(front) > len(back):
            front, back = back, front            # expand the smaller side
        moves += 1
        nxt_front = set()
        for state in front:
            for i in range(4):
                d = int(state[i])
                for nd in ((d + 1) % 10, (d - 1) % 10):
                    nxt = state[:i] + str(nd) + state[i + 1:]
                    if nxt in back:
                        return moves
                    if nxt not in seen and nxt not in dead:
                        seen.add(nxt)
                        nxt_front.add(nxt)
        front = nxt_front
    return -1
